import { Title } from "@solidjs/meta";
import { action, createAsync, query, useAction } from "@solidjs/router";
import { createSignal, Show } from "solid-js";
import { getRequestEvent } from "solid-js/web";
import {
  readContact,
  submitContact,
  validateContact,
  type ContactErrors,
  type ContactResult,
  type ContactValues
} from "~/lib/contact";

// The outcome of a form posted without JavaScript, validated by the middleware for this request.
const getPostedContact = query(async (): Promise<ContactResult | null> => {
  "use server";
  return getRequestEvent()?.locals.contact ?? null;
}, "postedContact");

const sendContact = action(async (values: ContactValues): Promise<ContactResult> => {
  "use server";
  return submitContact(values);
}, "sendContact");

export default function Contact() {
  const posted = createAsync(() => getPostedContact());
  const send = useAction(sendContact);
  const [sent, setSent] = createSignal<ContactResult | null>(null);
  const [pending, setPending] = createSignal(false);

  const result = () => sent() ?? posted() ?? null;
  const errors = (): ContactErrors => result()?.errors ?? {};
  const values = (): ContactValues => result()?.values ?? { name: "", email: "", message: "" };

  const onSubmit = async (e: SubmitEvent) => {
    e.preventDefault();
    const form = e.currentTarget as HTMLFormElement;
    const submitted = readContact(new FormData(form));
    const clientErrors = validateContact(submitted);
    if (Object.keys(clientErrors).length > 0) {
      setSent({ values: submitted, errors: clientErrors });
      return;
    }
    setPending(true);
    try {
      const outcome = await send(submitted);
      setSent(outcome);
      if (outcome.success) form.reset();
    } finally {
      setPending(false);
    }
  };

  return (
    <main>
      <Title>Contact | Bookshelf</Title>
      <h1>Contact</h1>
      <Show when={result()?.success}>
        {message => (
          <p role="status" class="success">
            {message()}
          </p>
        )}
      </Show>
      <form method="post" action="/contact" novalidate onSubmit={onSubmit} class="contact-form">
        <div class="field">
          <label for="contact-name">Name</label>
          <input
            id="contact-name"
            name="name"
            type="text"
            value={values().name}
            aria-invalid={errors().name ? "true" : undefined}
            aria-describedby={errors().name ? "contact-name-error" : undefined}
          />
          <Show when={errors().name}>
            <p id="contact-name-error" class="error">
              {errors().name}
            </p>
          </Show>
        </div>
        <div class="field">
          <label for="contact-email">Email</label>
          <input
            id="contact-email"
            name="email"
            type="email"
            value={values().email}
            aria-invalid={errors().email ? "true" : undefined}
            aria-describedby={errors().email ? "contact-email-error" : undefined}
          />
          <Show when={errors().email}>
            <p id="contact-email-error" class="error">
              {errors().email}
            </p>
          </Show>
        </div>
        <div class="field">
          <label for="contact-message">Message</label>
          <textarea
            id="contact-message"
            name="message"
            rows={6}
            value={values().message}
            aria-invalid={errors().message ? "true" : undefined}
            aria-describedby={errors().message ? "contact-message-error" : undefined}
          />
          <Show when={errors().message}>
            <p id="contact-message-error" class="error">
              {errors().message}
            </p>
          </Show>
        </div>
        <button type="submit" disabled={pending()}>
          Send
        </button>
      </form>
    </main>
  );
}
EOF
